//! macOS `NSPasteboard` backup, transient publish, privacy markers, and delayed restore (spec §7).
//!
//! Mirrors Windows' `clipboard.rs`:
//! - Backs up every item and pasteboard type up to `CLIPBOARD_BACKUP_MAX_FORMAT_BYTES`.
//! - Publishes Wren's UTF-8 text tagged with `org.nspasteboard.TransientType`,
//!   `org.nspasteboard.ConcealedType`, and `org.nspasteboard.AutoGeneratedType` so macOS clipboard
//!   managers (Raycast, Paste, Maccy, Alfred, etc.) keep dictated text out of clipboard history.
//! - Restores the previous pasteboard contents `CLIPBOARD_RESTORE_MS` after a paste ONLY if
//!   `NSPasteboard.changeCount` has not advanced (meaning no other app copied meanwhile).
//! - Serializes paste transactions and exposes [`flush`] so quitting Wren restores any pending
//!   clipboard backup before exiting.

use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use anyhow::anyhow;
use objc2::rc::Retained;
use objc2::runtime::ProtocolObject;
use objc2_app_kit::{NSPasteboard, NSPasteboardItem, NSPasteboardTypeString, NSPasteboardWriting};
use objc2_foundation::{NSArray, NSData, NSString};
use parking_lot::Mutex;

use crate::constants::{CLIPBOARD_BACKUP_MAX_FORMAT_BYTES, CLIPBOARD_RESTORE_MS};

/// Standard NSPasteboard marker types honored by macOS clipboard managers (nspasteboard.org).
const PRIVACY_MARKERS: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SavedItem {
    pub representations: Vec<(String, Vec<u8>)>,
}

/// Complete backup of the general pasteboard at one instant.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Snapshot {
    pub items: Vec<SavedItem>,
}

impl Snapshot {
    pub fn capture() -> anyhow::Result<Snapshot> {
        let _lock = transaction_lock();
        Ok(capture_now())
    }

    pub fn restore(&self) -> anyhow::Result<()> {
        let _lock = transaction_lock();
        restore_now(&self.items)
    }
}

fn capture_now() -> Snapshot {
    let pb = NSPasteboard::generalPasteboard();
    let Some(items) = pb.pasteboardItems() else {
        return Snapshot::default();
    };
    let mut saved = Vec::new();
    for item in items.iter() {
        let types = item.types();
        let mut reps = Vec::new();
        for pb_type in types.iter() {
            let type_name = pb_type.to_string();
            // Skip transient markers on backup so restore adds fresh markers cleanly.
            if PRIVACY_MARKERS.contains(&type_name.as_str()) {
                continue;
            }
            if let Some(data) = item.dataForType(&pb_type) {
                let len = data.len();
                if len == 0 || len > CLIPBOARD_BACKUP_MAX_FORMAT_BYTES {
                    if len > CLIPBOARD_BACKUP_MAX_FORMAT_BYTES {
                        tracing::warn!(type_name, len, "pasteboard item too large to back up; skipping");
                    }
                    continue;
                }
                reps.push((type_name, data.to_vec()));
            }
        }
        if !reps.is_empty() {
            saved.push(SavedItem { representations: reps });
        }
    }
    Snapshot { items: saved }
}

fn restore_now(items: &[SavedItem]) -> anyhow::Result<()> {
    let pb = NSPasteboard::generalPasteboard();
    pb.clearContents();
    if items.is_empty() {
        return Ok(());
    }
    let mut pb_items: Vec<Retained<NSPasteboardItem>> = Vec::with_capacity(items.len());
    for (idx, saved) in items.iter().enumerate() {
        let item = NSPasteboardItem::new();
        // Mark the restored clipboard as transient on the first item so clipboard managers don't
        // record a duplicate entry when Wren puts the user's previous copy back.
        if idx == 0 {
            let empty = NSData::new();
            let transient = NSString::from_str("org.nspasteboard.TransientType");
            let _ = item.setData_forType(&empty, &transient);
        }
        for (type_name, bytes) in &saved.representations {
            let t = NSString::from_str(type_name);
            let data = NSData::with_bytes(bytes);
            let _ = item.setData_forType(&data, &t);
        }
        pb_items.push(item);
    }
    let objects: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = pb_items
        .into_iter()
        .map(|i| ProtocolObject::from_retained(i))
        .collect();
    let array = NSArray::from_retained_slice(&objects);
    if !pb.writeObjects(&array) {
        return Err(anyhow!("NSPasteboard::writeObjects failed during restore"));
    }
    Ok(())
}

/// Publish plain UTF-8 text with clipboard-manager privacy markers and return the new `changeCount`.
fn publish_plain_text(text: &str) -> anyhow::Result<isize> {
    let pb = NSPasteboard::generalPasteboard();
    pb.clearContents();

    let item = NSPasteboardItem::new();
    let ns_text = NSString::from_str(text);
    let ok = unsafe { item.setString_forType(&ns_text, NSPasteboardTypeString) };
    if !ok {
        return Err(anyhow!("NSPasteboardItem::setString_forType failed"));
    }
    let empty = NSData::new();
    for marker in PRIVACY_MARKERS {
        let t = NSString::from_str(marker);
        let _ = item.setData_forType(&empty, &t);
    }

    let obj: Retained<ProtocolObject<dyn NSPasteboardWriting>> = ProtocolObject::from_retained(item);
    let array = NSArray::from_retained_slice(&[obj]);
    if !pb.writeObjects(&array) {
        return Err(anyhow!("NSPasteboard::writeObjects failed"));
    }
    Ok(pb.changeCount())
}

// ---- Pending-restore coordination ----

struct PendingRestore {
    flush_now: Arc<AtomicBool>,
    handle: JoinHandle<()>,
}

static PENDING: Mutex<Option<PendingRestore>> = Mutex::new(None);
static TX_MUTEX: Mutex<()> = Mutex::new(());

fn transaction_lock() -> parking_lot::MutexGuard<'static, ()> {
    flush();
    TX_MUTEX.lock()
}

/// If a previous paste is still waiting to restore the clipboard, restore it right now and wait
/// for the worker thread to finish. Called on Wren quit and before any new clipboard operation.
pub fn flush() {
    let pending = PENDING.lock().take();
    if let Some(p) = pending {
        p.flush_now.store(true, Ordering::SeqCst);
        let _ = p.handle.join();
    }
}

/// Copy `text` to the general pasteboard, marked out of clipboard managers.
pub fn copy_text(text: &str) -> anyhow::Result<()> {
    if text.is_empty() {
        return Err(anyhow!("nothing to copy"));
    }
    let _lock = transaction_lock();
    publish_plain_text(text)?;
    Ok(())
}

/// Active paste transaction: owns the backup snapshot and changeCount for restore verification.
pub struct Transaction {
    backup: Snapshot,
    own_change_count: isize,
    finished: bool,
}

impl Transaction {
    pub fn start(text: &str) -> anyhow::Result<Self> {
        let _lock = transaction_lock();
        let backup = capture_now();
        let own_change_count = publish_plain_text(text)?;
        Ok(Self {
            backup,
            own_change_count,
            finished: false,
        })
    }

    /// Leave Wren's text on the clipboard (e.g. focus changed or paste failed).
    pub fn leave_text(mut self) {
        self.finished = true;
    }

    /// Schedule the backup to be restored after `CLIPBOARD_RESTORE_MS`, unless another app wrote
    /// to the pasteboard in the meantime (`changeCount` changed).
    pub fn restore_later(mut self) {
        self.finished = true;
        let backup = Arc::new(std::mem::take(&mut self.backup));
        let backup_for_thread = backup.clone();
        let expected_count = self.own_change_count;
        let flush_now = Arc::new(AtomicBool::new(false));
        let f = flush_now.clone();

        let spawned = std::thread::Builder::new().name("wren-clipboard-restore".into()).spawn(move || {
            let deadline = Instant::now() + Duration::from_millis(CLIPBOARD_RESTORE_MS);
            while Instant::now() < deadline {
                if f.load(Ordering::SeqCst) {
                    break;
                }
                std::thread::sleep(Duration::from_millis(15));
            }
            let _lock = TX_MUTEX.lock();
            let pb = NSPasteboard::generalPasteboard();
            if should_restore(pb.changeCount(), expected_count) {
                if let Err(err) = restore_now(&backup_for_thread.items) {
                    tracing::warn!(error = %err, "failed to restore macOS pasteboard");
                }
            } else {
                tracing::debug!("pasteboard changed after paste; keeping user's newer copy");
            }
        });

        match spawned {
            Ok(handle) => {
                *PENDING.lock() = Some(PendingRestore { flush_now, handle });
            }
            Err(err) => {
                tracing::warn!(error = %err, "cannot spawn clipboard restore thread; restoring now");
                std::thread::sleep(Duration::from_millis(CLIPBOARD_RESTORE_MS));
                let pb = NSPasteboard::generalPasteboard();
                if should_restore(pb.changeCount(), expected_count) {
                    let _ = restore_now(&backup.items);
                }
            }
        }
    }
}

impl Drop for Transaction {
    fn drop(&mut self) {
        if !self.finished {
            let pb = NSPasteboard::generalPasteboard();
            if should_restore(pb.changeCount(), self.own_change_count) {
                let _ = restore_now(&self.backup.items);
            }
        }
    }
}

/// Pure decision: only restore if nobody else modified the pasteboard since Wren published.
pub fn should_restore(current_change_count: isize, own_change_count: isize) -> bool {
    current_change_count == own_change_count
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn restore_only_runs_when_change_count_matches() {
        assert!(should_restore(42, 42));
        assert!(!should_restore(43, 42));
        assert!(!should_restore(41, 42));
    }

    #[test]
    fn copy_text_rejects_empty() {
        assert!(copy_text("").is_err());
    }
}
